//! noevia#1318: native read-only `GET /api/v1/models` and `GET /api/v1/overview` through the
//! real router.
//!
//! On Linux every case of `fixtures/model-list-python.v1.json` (the actual services Python,
//! regenerated by CI from the pinned ref) runs through the router and the kernel-contained
//! opener, with a stand-in for the Python child that answers the private runtime calls with the
//! bodies the real routes placed for that case, and that records each request. Elsewhere that
//! opener refuses by design, which the refusal test asserts; the lib tests run the same cases on
//! every platform.
#![cfg(feature = "native-model-list")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{body::Body, http::Request};
use http_body_util::BodyExt;
use noevia_model_manager::{
    model_list::{DiskUsage, ModelList, Settings},
    Container, DockerRead, Redactor, StateData,
};
use std::{future::Future, path::Path, pin::Pin, sync::Arc};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";
const MODELS_RUNTIME: &str = "/api/v1/internal/models-runtime";
const OVERVIEW_RUNTIME: &str = "/api/v1/internal/overview-runtime";
const REFUSED: &[u8] = br#"{"detail":"Native model list is unavailable"}"#;
const UNAVAILABLE: &[u8] = br#"{"detail":"Python-owned endpoint unavailable"}"#;
/// A GGUF v3 header with one key: general.architecture = "synth".
const HEADER: &str =
    "474755460300000000000000000000000100000000000000140000000000000067656e6572616c2e61726368697465637475726508000000050000000000000073796e7468";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;
struct NoDocker;
impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

fn state(list: Option<Arc<ModelList>>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        model_updates: None,
        model_detail: None,
        model_list: list,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-section-autoconfig")]
        section_autoconfig: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        #[cfg(feature = "native-model-delete")]
        model_delete: None,
        #[cfg(feature = "native-draft-heads")]
        draft_heads: None,
        #[cfg(feature = "native-backends")]
        backend_stats: None,
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

/// Both routes native over `models`, `ini` and `data`, with the given disk numbers.
fn list(models: &Path, ini: &Path, data: &Path, host: &str, disk: (u128, u128)) -> Arc<ModelList> {
    let usage: DiskUsage = Arc::new(move |_: &Path| Ok(disk));
    Arc::new(ModelList::new(
        Settings {
            models: models.into(),
            ini: ini.into(),
            data: Some(data.into()),
            host_path: Some(host.into()),
        },
        usage,
    ))
}

struct Answer {
    status: u16,
    content_type: Option<String>,
    body: Vec<u8>,
}

async fn send(state: Arc<StateData>, method: &str, path: &str, token: bool) -> Answer {
    let mut request = Request::builder().method(method).uri(path);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();
    Answer {
        status: response.status().as_u16(),
        content_type: response
            .headers()
            .get("content-type")
            .map(|v| v.to_str().unwrap().to_owned()),
        body: response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes()
            .to_vec(),
    }
}

/// A one-shot stand-in for the Python child: records the request (head and body) and answers
/// `body` with `status`. Returns (base URL, request).
async fn child(status: u16, body: String) -> (String, tokio::task::JoinHandle<(String, String)>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let task = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut seen = Vec::new();
        let mut buf = [0u8; 4096];
        let end = loop {
            if let Some(at) = seen.windows(4).position(|w| w == b"\r\n\r\n") {
                break at + 4;
            }
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        };
        let head = String::from_utf8_lossy(&seen[..end]).into_owned();
        let length: usize = head
            .lines()
            .find_map(|l| {
                l.to_ascii_lowercase()
                    .strip_prefix("content-length: ")
                    .map(|v| v.trim().parse().unwrap())
            })
            .unwrap_or(0);
        while seen.len() < end + length {
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        }
        let request_body = String::from_utf8_lossy(&seen[end..end + length]).into_owned();
        let answer = format!(
            "HTTP/1.1 {status} X\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
            body.len()
        );
        socket.write_all(answer.as_bytes()).await.unwrap();
        socket.write_all(body.as_bytes()).await.unwrap();
        (head, request_body)
    });
    (base, task)
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

/// One model file `a.gguf` and a store with the badge table, under `root`. Returns
/// (models, ini, data).
fn folder(root: &Path) -> (std::path::PathBuf, std::path::PathBuf, std::path::PathBuf) {
    let models = root.join("models");
    std::fs::create_dir_all(&models).unwrap();
    std::fs::write(models.join("a.gguf"), hex(HEADER)).unwrap();
    let data = root.join("data");
    std::fs::create_dir_all(&data).unwrap();
    rusqlite::Connection::open(data.join("model_loader.db"))
        .unwrap()
        .execute_batch(
            "CREATE TABLE model_badge (id INTEGER PRIMARY KEY AUTOINCREMENT, alias TEXT NOT NULL, \
             category TEXT NOT NULL, rating INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', \
             run_id INTEGER, created_at REAL NOT NULL, UNIQUE(alias, category));",
        )
        .unwrap();
    let ini = models.join("models.ini");
    (models, ini, data)
}

#[tokio::test]
async fn python_mode_forwards_both_routes_unchanged() {
    for path in ["/api/v1/models", "/api/v1/overview"] {
        let (base, seen) = child(200, r#"{"legacy":true}"#.into()).await;
        let answer = send(state(None, &base), "GET", path, true).await;
        assert_eq!(answer.body, br#"{"legacy":true}"#);
        let (head, _) = seen.await.unwrap();
        assert!(
            head.starts_with(&format!("GET {path} HTTP/1.1\r\n")),
            "{head}"
        );
    }
}

#[tokio::test]
async fn the_private_runtime_calls_are_never_reachable_from_outside() {
    let dir = tempfile::tempdir().unwrap();
    let (models, ini, data) = folder(dir.path());
    for native in [None, Some(list(&models, &ini, &data, "", (1, 0)))] {
        for (method, path) in [
            ("POST", MODELS_RUNTIME),
            ("GET", MODELS_RUNTIME),
            ("GET", OVERVIEW_RUNTIME),
            ("GET", "/api/v1/internal/%6Fverview-runtime"),
        ] {
            let answer = send(
                state(native.clone(), "http://127.0.0.1:9"),
                method,
                path,
                true,
            )
            .await;
            assert_eq!(answer.status, 404, "{method} {path}");
            assert_eq!(answer.body, br#"{"detail":"Not Found"}"#);
        }
    }
}

#[tokio::test]
async fn native_routes_keep_auth_and_non_get_policy() {
    let dir = tempfile::tempdir().unwrap();
    let (models, ini, data) = folder(dir.path());
    let make = || {
        state(
            Some(list(&models, &ini, &data, "", (1, 0))),
            "http://127.0.0.1:9",
        )
    };
    for path in ["/api/v1/models", "/api/v1/overview"] {
        let unauthorized = send(make(), "GET", path, false).await;
        assert_eq!(unauthorized.status, 401);
        assert_eq!(unauthorized.body, br#"{"error":"unauthorized"}"#);
        for method in ["POST", "PUT", "DELETE", "HEAD"] {
            let answer = send(make(), method, path, true).await;
            assert_eq!(answer.status, 405, "{method} {path}");
        }
    }
}

#[cfg(not(target_os = "linux"))]
#[tokio::test]
async fn without_the_contained_opener_the_list_refuses() {
    let dir = tempfile::tempdir().unwrap();
    let (models, ini, data) = folder(dir.path());
    let answer = send(
        state(
            Some(list(&models, &ini, &data, "", (1, 0))),
            "http://127.0.0.1:9",
        ),
        "GET",
        "/api/v1/models",
        true,
    )
    .await;
    assert_eq!(answer.status, 503);
    assert_eq!(answer.body, REFUSED);
}

#[cfg(target_os = "linux")]
mod linux {
    use super::*;
    use serde_json::Value;

    fn fixture() -> Value {
        serde_json::from_str(include_str!("fixtures/model-list-python.v1.json")).unwrap()
    }

    fn time(ns: i128) -> std::time::SystemTime {
        let magnitude = std::time::Duration::from_nanos(u64::try_from(ns.unsigned_abs()).unwrap());
        if ns >= 0 {
            std::time::UNIX_EPOCH + magnitude
        } else {
            std::time::UNIX_EPOCH - magnitude
        }
    }

    /// Builds one case like the generator does; returns (models, ini, data).
    fn build(
        root: &Path,
        case: &Value,
    ) -> (std::path::PathBuf, std::path::PathBuf, std::path::PathBuf) {
        let models = root.join("models");
        let mut ini = models.join("models.ini");
        for name in case["outside"].as_array().into_iter().flatten() {
            std::fs::write(root.join(name.as_str().unwrap()), b"GGUF").unwrap();
        }
        if let Some(text) = case["ini_outside"]["text"].as_str() {
            ini = root.join("models.ini");
            std::fs::write(&ini, text).unwrap();
        }
        match case["models"].as_str().unwrap_or("dir") {
            "missing" => {}
            "file" => std::fs::write(&models, b"").unwrap(),
            kind => {
                if kind == "link" {
                    let real = root.join("real-models");
                    std::fs::create_dir(&real).unwrap();
                    std::os::unix::fs::symlink(&real, &models).unwrap();
                } else {
                    std::fs::create_dir(&models).unwrap();
                }
                for dir in case["dirs"].as_array().into_iter().flatten() {
                    std::fs::create_dir_all(models.join(dir.as_str().unwrap())).unwrap();
                }
                let files = case["files"].as_array().cloned().unwrap_or_default();
                for file in &files {
                    let path = models.join(file["name"].as_str().unwrap());
                    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
                    std::fs::write(&path, hex(file["hex"].as_str().unwrap())).unwrap();
                    if let Some(size) = file["size"].as_u64() {
                        std::fs::File::options()
                            .write(true)
                            .open(&path)
                            .unwrap()
                            .set_len(size)
                            .unwrap();
                    }
                }
                for link in case["links"].as_array().into_iter().flatten() {
                    std::os::unix::fs::symlink(
                        link[1].as_str().unwrap(),
                        models.join(link[0].as_str().unwrap()),
                    )
                    .unwrap();
                }
                for link in case["abslinks"].as_array().into_iter().flatten() {
                    let target = std::fs::canonicalize(&models)
                        .unwrap()
                        .join(link[1].as_str().unwrap());
                    std::os::unix::fs::symlink(target, models.join(link[0].as_str().unwrap()))
                        .unwrap();
                }
                match &case["ini"] {
                    Value::Null => {}
                    Value::String(s) if s == "dir" => std::fs::create_dir(&ini).unwrap(),
                    Value::Object(o) => {
                        let bytes = match o.get("text") {
                            Some(text) => text.as_str().unwrap().as_bytes().to_vec(),
                            None => hex(o["hex"].as_str().unwrap()),
                        };
                        std::fs::write(&ini, bytes).unwrap();
                    }
                    other => panic!("unknown ini {other}"),
                }
                for file in &files {
                    let ns = file["mtime"]
                        .as_i64()
                        .map(i128::from)
                        .or_else(|| file["mtime"].as_u64().map(i128::from))
                        .unwrap();
                    let t = time(ns);
                    std::fs::File::options()
                        .write(true)
                        .open(models.join(file["name"].as_str().unwrap()))
                        .unwrap()
                        .set_times(std::fs::FileTimes::new().set_accessed(t).set_modified(t))
                        .unwrap();
                }
            }
        }
        let data = root.join("data");
        std::fs::create_dir_all(&data).unwrap();
        let statements: Vec<&str> = case["store"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap())
            .collect();
        rusqlite::Connection::open(data.join("model_loader.db"))
            .unwrap()
            .execute_batch(&statements.join("\n"))
            .unwrap();
        (models, ini, data)
    }

    fn disk(case: &Value) -> (u128, u128) {
        match case["disk"].as_array() {
            Some(pair) => (
                u128::from(pair[0].as_u64().unwrap()),
                u128::from(pair[1].as_u64().unwrap()),
            ),
            None => (4_000_000_000_000, 1_234_567_890_123),
        }
    }

    fn refuses(case: &Value, route: &str) -> bool {
        case["native_refuses"]
            .as_array()
            .is_some_and(|routes| routes.iter().any(|r| r == route))
    }

    #[tokio::test]
    async fn every_case_matches_the_actual_python_routes_through_the_router() {
        let fixture = fixture();
        let mut checked = 0;
        for case in fixture["cases"].as_array().unwrap() {
            let tmp = tempfile::tempdir().unwrap();
            let (models, ini, data) = build(tmp.path(), case);
            let host = case["host_path"].as_str().unwrap_or_default();
            let native = list(&models, &ini, &data, host, disk(case));
            let prefix = serde_json::to_string(models.to_str().unwrap()).unwrap();
            let prefix = prefix[1..prefix.len() - 1].to_owned();
            let results = &case["results"];
            // GET /api/v1/models: the child answers its recorded live fields when asked.
            let runtime = &results["models_runtime"];
            let (base, seen) = if runtime.is_null() {
                ("http://127.0.0.1:9".to_owned(), None)
            } else {
                let (base, seen) = child(200, runtime["body"].as_str().unwrap().into()).await;
                (base, Some(seen))
            };
            let answer = send(
                state(Some(native.clone()), &base),
                "GET",
                "/api/v1/models",
                true,
            )
            .await;
            let python = &results["models"];
            if refuses(case, "models") {
                assert_eq!(answer.status, 503, "{}", case["id"]);
                assert_eq!(answer.body, REFUSED);
            } else {
                assert_eq!(
                    (answer.status, String::from_utf8(answer.body).unwrap()),
                    (
                        u16::try_from(python["status"].as_u64().unwrap()).unwrap(),
                        python["body"].as_str().unwrap().to_owned()
                    ),
                    "case {} models",
                    case["id"]
                );
                assert_eq!(
                    answer.content_type.as_deref(),
                    python["content_type"].as_str(),
                    "case {}",
                    case["id"]
                );
                if python["status"] == 200 {
                    let (head, body) = seen.unwrap().await.unwrap();
                    assert!(
                        head.starts_with(&format!("POST {MODELS_RUNTIME} HTTP/1.1\r\n")),
                        "{head}"
                    );
                    let lower = head.to_ascii_lowercase();
                    assert!(lower.contains(&format!("x-model-loader-token: {TOKEN}\r\n")));
                    assert!(lower.contains("content-type: application/json\r\n"));
                    let sizes: Vec<String> = runtime["sizes"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(Value::to_string)
                        .collect();
                    assert_eq!(body, format!("{{\"bytes\":[{}]}}", sizes.join(",")));
                }
            }
            // GET /api/v1/overview.
            let python = &results["overview"];
            let (base, seen) =
                child(200, results["overview_runtime"].as_str().unwrap().into()).await;
            let answer = send(state(Some(native), &base), "GET", "/api/v1/overview", true).await;
            let body = String::from_utf8(answer.body)
                .unwrap()
                .replace(&prefix, "@MODELS@");
            assert_eq!(
                (answer.status, body.as_str()),
                (
                    u16::try_from(python["status"].as_u64().unwrap()).unwrap(),
                    python["body"].as_str().unwrap()
                ),
                "case {} overview",
                case["id"]
            );
            assert_eq!(
                answer.content_type.as_deref(),
                python["content_type"].as_str()
            );
            if python["status"] == 200 {
                let (head, body) = seen.await.unwrap();
                assert!(
                    head.starts_with(&format!("GET {OVERVIEW_RUNTIME} HTTP/1.1\r\n")),
                    "{head}"
                );
                assert!(head
                    .to_ascii_lowercase()
                    .contains(&format!("x-model-loader-token: {TOKEN}\r\n")));
                assert!(body.is_empty());
            }
            checked += 1;
        }
        assert!(checked >= 28, "{checked}");
    }

    #[tokio::test]
    async fn a_child_that_cannot_answer_is_never_guessed_around() {
        let dir = tempfile::tempdir().unwrap();
        let (models, ini, data) = folder(dir.path());
        let native = || list(&models, &ini, &data, "", (1, 0));
        for path in ["/api/v1/models", "/api/v1/overview"] {
            // The child's own unhandled error is Python's 500.
            let (base, _seen) = child(500, "Internal Server Error".into()).await;
            let failed = send(state(Some(native()), &base), "GET", path, true).await;
            assert_eq!(failed.status, 500, "{path}");
            assert_eq!(
                failed.content_type.as_deref(),
                Some("text/plain; charset=utf-8")
            );
            assert_eq!(failed.body, b"Internal Server Error");
            // Refusing, missing or malformed: the forwarded route's 502, never a partial answer.
            for (status, body) in [
                (
                    503,
                    r#"{"detail":"Native model manager owns this endpoint"}"#,
                ),
                (404, r#"{"detail":"Not Found"}"#),
                (200, r#"{"loaded":{}}"#),
                (200, r#"{"loaded":{},"fit":[]}"#),
                (200, r#"{"backends":{},"activeDownloads":0}"#),
                (200, "not json"),
            ] {
                let (base, _seen) = child(status, body.into()).await;
                let answer = send(state(Some(native()), &base), "GET", path, true).await;
                assert_eq!(answer.status, 502, "{path} {status} {body}");
                assert_eq!(answer.body, UNAVAILABLE);
            }
            let down = send(
                state(Some(native()), "http://127.0.0.1:9"),
                "GET",
                path,
                true,
            )
            .await;
            assert_eq!(down.status, 502);
            assert_eq!(down.body, UNAVAILABLE);
        }
        // A file part that fails is answered without asking the child at all.
        std::fs::write(&ini, "[a]\nbroken\n").unwrap();
        for path in ["/api/v1/models", "/api/v1/overview"] {
            let failed = send(
                state(Some(native()), "http://127.0.0.1:9"),
                "GET",
                path,
                true,
            )
            .await;
            assert_eq!(failed.status, 500, "{path}");
        }
    }

    #[tokio::test]
    async fn a_store_without_the_badge_table_fails_the_list_after_the_child() {
        let dir = tempfile::tempdir().unwrap();
        let (models, ini, data) = folder(dir.path());
        rusqlite::Connection::open(data.join("model_loader.db"))
            .unwrap()
            .execute_batch("DROP TABLE model_badge;")
            .unwrap();
        let (base, seen) = child(200, r#"{"loaded":{},"fit":[[]]}"#.into()).await;
        let answer = send(
            state(Some(list(&models, &ini, &data, "", (1, 0))), &base),
            "GET",
            "/api/v1/models",
            true,
        )
        .await;
        assert_eq!(answer.status, 500);
        assert_eq!(answer.body, b"Internal Server Error");
        let (head, _) = seen.await.unwrap();
        assert!(head.starts_with(&format!("POST {MODELS_RUNTIME} ")));
        // A store that does not exist is not created.
        std::fs::remove_file(data.join("model_loader.db")).unwrap();
        let (base, _seen) = child(200, r#"{"loaded":{},"fit":[[]]}"#.into()).await;
        let answer = send(
            state(Some(list(&models, &ini, &data, "", (1, 0))), &base),
            "GET",
            "/api/v1/models",
            true,
        )
        .await;
        assert_eq!(answer.status, 500);
        assert!(!data.join("model_loader.db").exists());
    }

    #[tokio::test]
    async fn a_section_path_leaving_the_folder_refuses_only_the_list() {
        let dir = tempfile::tempdir().unwrap();
        let (models, ini, data) = folder(dir.path());
        std::fs::write(dir.path().join("outside.gguf"), hex(HEADER)).unwrap();
        std::fs::write(&ini, "[a]\nmodel = ../outside.gguf\n").unwrap();
        let native = list(&models, &ini, &data, "", (1, 0));
        let answer = send(
            state(Some(native.clone()), "http://127.0.0.1:9"),
            "GET",
            "/api/v1/models",
            true,
        )
        .await;
        assert_eq!(answer.status, 503);
        assert_eq!(answer.body, REFUSED);
        let (base, _seen) = child(200, r#"{"backends":[],"activeDownloads":0}"#.into()).await;
        let overview = send(state(Some(native), &base), "GET", "/api/v1/overview", true).await;
        assert_eq!(overview.status, 200);
    }

    /// While this process owns the download table, the overview counts its jobs, not the child's.
    #[cfg(feature = "native-downloads")]
    #[tokio::test]
    async fn the_native_download_table_is_counted_instead_of_the_childs() {
        let dir = tempfile::tempdir().unwrap();
        let (models, ini, data) = folder(dir.path());
        let table = noevia_model_manager::downloads::Downloads::new(
            noevia_model_manager::downloads::Config::production(
                models.to_str().unwrap().to_owned(),
                data.to_str().unwrap(),
                2,
            ),
        )
        .unwrap();
        let (base, _seen) = child(200, r#"{"backends":[],"activeDownloads":3}"#.into()).await;
        let mut with_table =
            Arc::into_inner(state(Some(list(&models, &ini, &data, "", (1, 0))), &base)).unwrap();
        with_table.downloads = Some(table);
        let answer = send(Arc::new(with_table), "GET", "/api/v1/overview", true).await;
        assert_eq!(answer.status, 200);
        let body: Value = serde_json::from_slice(&answer.body).unwrap();
        assert_eq!(body["activeDownloads"], 0);
        // Without the table, the child's count is answered.
        let (base, _seen) = child(200, r#"{"backends":[],"activeDownloads":3}"#.into()).await;
        let answer = send(
            state(Some(list(&models, &ini, &data, "", (1, 0))), &base),
            "GET",
            "/api/v1/overview",
            true,
        )
        .await;
        let body: Value = serde_json::from_slice(&answer.body).unwrap();
        assert_eq!(body["activeDownloads"], 3);
    }
}
